using System.Text.Json;
using Clary.Api.Identity;
using Npgsql;
using NpgsqlTypes;
namespace Clary.Api;
public sealed partial class TicketRepository {
 internal static async Task Exists(NpgsqlConnection conn,NpgsqlTransaction tx,CompanyContext c,string table,Guid? id,CancellationToken ct){if(id is null)return;await using var q=Q(conn,tx,c,$"SELECT 1 FROM {table} WHERE company_id=@company AND id=@id"+(table=="documents"?"":" AND active"));q.Parameters.AddWithValue("id",id.Value);if(await q.ExecuteScalarAsync(ct) is null)throw new ArgumentException("Choose an active record from this company.");}
 public async Task<TicketDto> SaveAsync(CompanyContext c,Guid? id,TicketInput input,CancellationToken ct){
  await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);
  var result=await SaveWithinAsync(conn,tx,c,id,input,ct);await tx.CommitAsync(ct);return result;
 }
 // Shared transaction lets Brie commit its durable retry receipt with the existing business operation.
 internal async Task<TicketDto> SaveWithinAsync(NpgsqlConnection conn,NpgsqlTransaction tx,CompanyContext c,Guid? id,TicketInput input,CancellationToken ct){
  var title=Text(input.Title,200,true);var description=Text(input.Description,8000);if(!new[]{"Support","Equipment","Onboarding","Repair","Retirement"}.Contains(input.Type))throw new ArgumentException("Choose a valid ticket type.");if(input.DueDate is null&&id is null)throw new ArgumentException("Choose a due date.");if(input.AssignmentMode is not ("Users" or "All"))throw new ArgumentException("Choose users or All.");
  if(input.Priority is not null&&!new[]{"Low","Normal","High","Urgent"}.Contains(input.Priority))throw new ArgumentException("Choose a valid priority.");
  var users=(input.AssigneeIds??[]).Distinct().ToArray();var assets=input.AssetLinks??[];var docs=(input.DocumentIds??[]).Distinct().ToArray();if(users.Length>100||assets.Count>100||docs.Length>30||assets.Select(a=>a.AssetId).Distinct().Count()!=assets.Count)throw new ArgumentException("Too many or duplicate connections.");if(input.Type is "Equipment" or "Onboarding"&&input.RecipientEmployeeId is null)throw new ArgumentException("Choose the equipment recipient.");
  c=await TicketAccess.LiveAsync(conn,tx,c,ct);if(!TicketAccess.Manager(c))throw new CompanyDenied();
  TicketDto? before=null;if(id is {} existing){await Lock(conn,tx,c,existing,ct);before=await Get(conn,tx,c,existing,ct)??throw new InventoryMissing();if(before.IsWorkspaceSetup)throw new InventoryConflict("Use the setup checklist or delete this optional ticket.");if(before.Revision!=input.Revision||before.Status is "Complete" or "Canceled")throw new InventoryConflict("This ticket changed. Refresh it before editing.");if(before.RequestId is not null&&(before.RecipientEmployeeId!=input.RecipientEmployeeId||before.Type!=input.Type))throw new ArgumentException("Change the recipient through its linked request.");}
  await Exists(conn,tx,c,"employees",input.RecipientEmployeeId,ct);await Exists(conn,tx,c,"inventory_departments",input.DepartmentId,ct);await Exists(conn,tx,c,"locations",input.LocationId,ct);
  foreach(var user in users){await using var q=Q(conn,tx,c,"SELECT 1 FROM memberships m JOIN users u ON u.id=m.user_id WHERE m.company_id=@company AND m.user_id=@assigned AND m.active AND u.active");q.Parameters.AddWithValue("assigned",user);if(await q.ExecuteScalarAsync(ct) is null)throw new ArgumentException("Choose active company users.");}
  foreach(var doc in docs)await Exists(conn,tx,c,"documents",doc,ct);
  IReadOnlyList<EquipmentLine> lines=before?.Lines??[];if(input.KitId is {} kit){await using var q=Q(conn,tx,c,"SELECT lines::text FROM equipment_kits WHERE company_id=@company AND id=@kit AND active");q.Parameters.AddWithValue("kit",kit);var raw=await q.ExecuteScalarAsync(ct) as string??throw new ArgumentException("Choose an active kit.");lines=JsonSerializer.Deserialize<EquipmentLine[]>(raw,Json)!;}
  var ticket=id??Guid.NewGuid();var assigned=input.AssignmentMode=="All"||users.Length>0;var status=before?.Status??"Pending";if(status is "Approved" or "Assigned")status=assigned?"Assigned":"Approved";
  await using(var q=Q(conn,tx,c,id is null?"INSERT INTO equipment_tickets(id,company_id,title,state,type,description,due_date,recipient_employee_id,department_id,location_id,assignment_mode,creator_user_id,creator_name,fulfillment_lines,priority) VALUES(@id,@company,@title,@state,@type,@description,@due,@recipient,@department,@location,@mode,@user,@actor,@lines,@priority)":"UPDATE equipment_tickets SET title=@title,state=@state,type=@type,description=@description,due_date=@due,recipient_employee_id=@recipient,department_id=@department,location_id=@location,assignment_mode=@mode,fulfillment_lines=@lines,priority=@priority,revision=revision+1,updated_at=now() WHERE company_id=@company AND id=@id")){q.Parameters.AddWithValue("id",ticket);q.Parameters.AddWithValue("priority",input.Priority??before?.Priority??"Normal");q.Parameters.AddWithValue("title",title);q.Parameters.AddWithValue("state",status);q.Parameters.AddWithValue("type",input.Type);P(q,"description",description,NpgsqlDbType.Text);P(q,"due",input.DueDate,NpgsqlDbType.Date);P(q,"recipient",input.RecipientEmployeeId,NpgsqlDbType.Uuid);P(q,"department",input.DepartmentId,NpgsqlDbType.Uuid);P(q,"location",input.LocationId,NpgsqlDbType.Uuid);q.Parameters.AddWithValue("mode",input.AssignmentMode);q.Parameters.AddWithValue("actor",await Actor(conn,tx,c,ct));q.Parameters.AddWithValue("lines",NpgsqlDbType.Jsonb,JsonSerializer.Serialize(lines,Json));await q.ExecuteNonQueryAsync(ct);}
  await using(var q=Q(conn,tx,c,"DELETE FROM ticket_assignees WHERE company_id=@company AND ticket_id=@id; DELETE FROM ticket_document_links WHERE company_id=@company AND ticket_id=@id")){q.Parameters.AddWithValue("id",ticket);await q.ExecuteNonQueryAsync(ct);}
  if(input.AssignmentMode=="Users")foreach(var user in users){await using var q=Q(conn,tx,c,"INSERT INTO ticket_assignees(company_id,ticket_id,user_id) VALUES(@company,@id,@assigned)");q.Parameters.AddWithValue("id",ticket);q.Parameters.AddWithValue("assigned",user);await q.ExecuteNonQueryAsync(ct);}
  var documents=docs.ToList();if(id is null&&input.Type=="Onboarding"){await using var guide=Q(conn,tx,c,"SELECT onboarding_document_id FROM ticket_settings WHERE company_id=@company");if(await guide.ExecuteScalarAsync(ct) is Guid guideId&&!documents.Contains(guideId))documents.Add(guideId);}
  foreach(var doc in documents){await using var q=Q(conn,tx,c,"INSERT INTO ticket_document_links(company_id,ticket_id,id,document_id,document_title) SELECT @company,@ticket,@id,id,title FROM documents WHERE company_id=@company AND id=@doc");q.Parameters.AddWithValue("ticket",ticket);q.Parameters.AddWithValue("id",Guid.NewGuid());q.Parameters.AddWithValue("doc",doc);await q.ExecuteNonQueryAsync(ct);}
  var checklist=input.Checklist is null?before?.Checklist??[]:ChecklistText(input.Checklist).Select(text=>before?.Checklist.FirstOrDefault(x=>x.Text==text)??new TicketChecklistItem(Guid.NewGuid(),text)).ToArray();
  await using(var q=Q(conn,tx,c,"UPDATE equipment_tickets SET checklist=@checklist WHERE company_id=@company AND id=@id")){q.Parameters.AddWithValue("id",ticket);q.Parameters.AddWithValue("checklist",NpgsqlDbType.Jsonb,JsonSerializer.Serialize(checklist,Json));await q.ExecuteNonQueryAsync(ct);}
  await SaveAssetLinks(conn,tx,c,ticket,assets,ct);
  var ready=(await Get(conn,tx,c,ticket,ct))!;if(ready.Type is "Equipment" or "Onboarding" && ready.Lines.Count>0)await Fulfillment(conn,tx,c,ready,null,ct);
  if(before?.RequestId is {} request){if(description.Length>4000)throw new ArgumentException("Linked request instructions must be up to 4000 characters.");await using var q=Q(conn,tx,c,"UPDATE equipment_requests SET title=@title,notes=@description,needed_date=@due,revision=revision+1 WHERE company_id=@company AND id=@request");q.Parameters.AddWithValue("request",request);q.Parameters.AddWithValue("title",title);P(q,"description",description,NpgsqlDbType.Text);P(q,"due",input.DueDate,NpgsqlDbType.Date);await q.ExecuteNonQueryAsync(ct);}
  await Activity(conn,tx,c,ticket,id is null?"Created":"Updated",id is null?null:"Information, connections, or task assignments updated",ct);var after=(await Get(conn,tx,c,ticket,ct))!;await AuditRepository.AppendAsync(conn,tx,c,id is null?"Created":"Updated","equipment-ticket",ticket,before,after,ct);return after;
 }
 internal static async Task Lock(NpgsqlConnection conn,NpgsqlTransaction tx,CompanyContext c,Guid id,CancellationToken ct){await using var q=Q(conn,tx,c,"SELECT id FROM equipment_tickets WHERE company_id=@company AND id=@id FOR UPDATE");q.Parameters.AddWithValue("id",id);if(await q.ExecuteScalarAsync(ct) is null)throw new InventoryMissing();}
 public async Task<TicketCommentDto> AddCommentAsync(CompanyContext c,Guid id,TicketCommentInput input,CancellationToken ct){var body=Text(input.Body,4000,true);await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);c=await TicketAccess.LiveAsync(conn,tx,c,ct);var ticket=await Get(conn,tx,c,id,ct)??throw new InventoryMissing();if(!TicketAccess.Assigned(ticket,c)&&!TicketAccess.Administrator(c))throw new CompanyDenied();var actor=await Actor(conn,tx,c,ct);var comment=Guid.NewGuid();await using var q=Q(conn,tx,c,"INSERT INTO ticket_comments(company_id,ticket_id,id,author_user_id,author_name,body) VALUES(@company,@ticket,@id,@user,@actor,@body) RETURNING created_at");q.Parameters.AddWithValue("ticket",id);q.Parameters.AddWithValue("id",comment);q.Parameters.AddWithValue("actor",actor);q.Parameters.AddWithValue("body",body);var at=(DateTime)(await q.ExecuteScalarAsync(ct))!;await tx.CommitAsync(ct);return new(comment,c.UserId,actor,body,at);}
 public async Task<TicketPage<JsonElement>> FeedAsync(CompanyContext c,Guid id,bool comments,int limit,string? cursor,CancellationToken ct){if(limit is <1 or >100)throw new ArgumentException("Limit must be 1 to 100.");await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);c=await TicketAccess.LiveAsync(conn,tx,c,ct);if(await Get(conn,tx,c,id,ct) is null)throw new InventoryMissing();Cursor? after=null;if(cursor is not null){try{after=JsonSerializer.Deserialize<Cursor>(Convert.FromBase64String(cursor),Json);}catch(Exception ex)when(ex is FormatException or JsonException){throw new ArgumentException("Invalid cursor.");}if(after?.Company!=c.CompanyId)throw new ArgumentException("Invalid cursor.");}
  await using var q=Q(conn,tx,c,"SELECT "+(comments?"jsonb_build_object('id',id,'authorUserId',author_user_id,'authorName',author_name,'body',body,'createdAt',created_at)":"jsonb_build_object('id',id,'actorName',actor_name,'action',action,'detail',detail,'createdAt',created_at)")+"::text,id,created_at FROM "+(comments?"ticket_comments":"ticket_activity")+" WHERE company_id=@company AND ticket_id=@ticket AND (@after IS NULL OR (created_at,id)<(@after,@afterId)) ORDER BY created_at DESC,id DESC LIMIT @limit");q.Parameters.AddWithValue("ticket",id);P(q,"after",after?.CreatedAt,NpgsqlDbType.TimestampTz);q.Parameters.AddWithValue("afterId",after?.Id??Guid.Empty);q.Parameters.AddWithValue("limit",limit+1);var rows=new List<(JsonElement Item,Guid Id,DateTime At)>();await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))rows.Add((JsonSerializer.Deserialize<JsonElement>(r.GetString(0)),r.GetGuid(1),r.GetDateTime(2)));var more=rows.Count>limit;if(more)rows.RemoveAt(rows.Count-1);return new(rows.Select(x=>x.Item).ToArray(),more?Convert.ToBase64String(JsonSerializer.SerializeToUtf8Bytes(new Cursor(c.CompanyId,rows[^1].At,rows[^1].Id),Json)):null);
 }
 public async Task<TicketSettings> SettingsAsync(CompanyContext c,TicketSettings? input,CancellationToken ct){await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);c=await TicketAccess.LiveAsync(conn,tx,c,ct);if(!AccountPermissions.Allows(c,CompanyCapability.Read))throw new CompanyDenied();if(input is not null){if(!AccountPermissions.Allows(c,CompanyCapability.Settings))throw new CompanyDenied();await Exists(conn,tx,c,"documents",input.OnboardingDocumentId,ct);await using var save=Q(conn,tx,c,"INSERT INTO ticket_settings(company_id,onboarding_document_id) VALUES(@company,@doc) ON CONFLICT(company_id) DO UPDATE SET onboarding_document_id=excluded.onboarding_document_id");P(save,"doc",input.OnboardingDocumentId,NpgsqlDbType.Uuid);await save.ExecuteNonQueryAsync(ct);}await using var q=Q(conn,tx,c,"SELECT onboarding_document_id FROM ticket_settings WHERE company_id=@company");var value=await q.ExecuteScalarAsync(ct);await tx.CommitAsync(ct);return new(value is Guid id?id:null);}
}
